.product-card:hover .product-image { transform: scale(1.04); }
.product-image--1 { background: linear-gradient(160deg, #e8d8c4 0%, #c8a880 100%); }
.product-image--2 { background: linear-gradient(160deg, #f5ede0 0%, #d4b89c 100%); }
.product-image--3 { background: linear-gradient(160deg, #f0ebe3 0%, #c8bfb0 100%); }
.product-image--4 { background: linear-gradient(160deg, #d8c4a0 0%, #a08060 100%); }
.product-badge {
  position: absolute; top: var(--space-3); left: var(--space-3);
  padding: 2px 10px; border-radius: var(--r-full);
  font-size: 0.75rem; font-weight: 700; letter-spacing: .05em; text-transform: uppercase;
  background: var(--color-brand); color: var(--color-white);
}
.product-badge--sale       { background: var(--color-accent); }
.product-badge--bestseller { background: #9c6a00; }
.product-info { padding: var(--space-4); }
.product-brand {
  font-size: 0.75rem; font-weight: 600; letter-spacing: .08em;
  text-transform: uppercase; color: var(--color-gray-400); margin-bottom: var(--space-1);
}
.product-name { font-size: 0.9375rem; font-weight: 600; margin-bottom: var(--space-2); line-height: 1.3; }
.product-name a { color: var(--color-gray-900); }
.product-name a:hover { color: var(--color-brand); text-decoration: underline; text-underline-offset: 2px; }
.product-price { font-size: 1rem; font-weight: 700; color: var(--color-brand); margin-bottom: var(--space-4); }
.price-current  { color: var(--color-accent); }
.price-original { font-size: 0.875rem; font-weight: 400; color: var(--color-gray-400); margin-left: var(--space-2); }
.product-actions { display: flex; gap: var(--space-2); align-items: center; }

/* ── Deals ──────────────────────────────────────────────────── */
.deals-section { padding: var(--space-16) 0; background: var(--color-brand); }
.deals-section .section-header h2 { color: var(--color-white); }
.deals-section .view-all-link { color: rgba(255,255,255,.8); }
.deals-section .view-all-link:hover { color: var(--color-white); }
.deals-grid {
  max-width: var(--max-width); margin: 0 auto; padding: 0 var(--page-padding);
  display: grid; grid-template-columns: 1.6fr 1fr 1fr; gap: var(--space-5);
}
.deal-card {
  border-radius: var(--r-lg); overflow: hidden;
  background: var(--color-brand-mid); position: relative;
  display: flex; flex-direction: column;
}
.deal-card--hero { grid-row: span 2; }
.deal-image { flex: 1; min-height: 200px; }
.deal-card--hero .deal-image { min-height: 340px; }
.deal-image--1 { background: linear-gradient(160deg, #3a4a7a 0%, #8090c0 100%); }
.deal-image--2 { background: linear-gradient(160deg, #2a4060 0%, #6080a0 100%); }
.deal-image--3 { background: linear-gradient(160deg, #1a3050 0%, #4070a0 100%); }
.deal-content { padding: var(--space-5) var(--space-6); color: var(--color-white); }
.deal-tag {
  display: inline-block; background: var(--color-accent); color: var(--color-white);
  font-size: 0.6875rem; font-weight: 700; letter-spacing: .1em; text-transform: uppercase;
  padding: 3px 10px; border-radius: var(--r-full); margin-bottom: var(--space-3);
}
.deal-content h3 {
  font-size: clamp(1.125rem, 2vw, 1.5rem);
  font-weight: 700; letter-spacing: -0.02em; margin-bottom: var(--space-2);
}
.deal-content p { font-size: 0.9375rem; color: rgba(255,255,255,.75); margin-bottom: var(--space-5); }

/* ── Editorial ──────────────────────────────────────────────── */
.editorial-section { padding: var(--space-16) 0; background: var(--color-off-white); }
.editorial-grid {
  max-width: var(--max-width); margin: 0 auto; padding: 0 var(--page-padding);
  display: grid; grid-template-columns: 1.5fr 1fr 1fr; gap: var(--space-6);
}
.editorial-card {
  border-radius: var(--r-lg); overflow: hidden;
  background: var(--color-white); box-shadow: var(--shadow-sm);
  transition: box-shadow var(--t-base), transform var(--t-base);
  display: flex; flex-direction: column;
}
.editorial-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-2px); }
.editorial-image { aspect-ratio: 16/9; transition: transform var(--t-base); overflow: hidden; }
.editorial-card--large .editorial-image { aspect-ratio: 4/3; }
.editorial-card:hover .editorial-image { transform: scale(1.03); }
.editorial-image--1 { background: linear-gradient(135deg, #d4e8c4 0%, #8cb080 100%); }
.editorial-image--2 { background: linear-gradient(135deg, #f5e4d0 0%, #d4a080 100%); }
.editorial-image--3 { background: linear-gradient(135deg, #d4e4f5 0%, #80a0c4 100%); }
.editorial-content { padding: var(--space-5); flex: 1; display: flex; flex-direction: column; }
.editorial-tag {
  display: inline-block; font-size: 0.6875rem; font-weight: 700;
  letter-spacing: .1em; text-transform: uppercase; color: var(--color-accent);
  margin-bottom: var(--space-2);
}
.editorial-content h3 { font-size: 1.0625rem; font-weight: 700; line-height: 1.35; margin-bottom: var(--space-2); flex: 1; }
.editorial-card--large .editorial-content h3 { font-size: 1.375rem; }
.editorial-content h3 a { color: var(--color-gray-900); }
.editorial-content h3 a:hover { color: var(--color-brand); text-decoration: underline; text-underline-offset: 2px; }
.editorial-content p { font-size: 0.9rem; color: var(--color-gray-600); margin-bottom: var(--space-3); }
.editorial-meta {
  font-size: 0.8125rem; color: var(--color-gray-400);
  margin-top: auto; padding-top: var(--space-3);
  border-top: 1px solid var(--color-gray-100);
}

/* ── Newsletter ─────────────────────────────────────────────── */
.newsletter-section {
  padding: var(--space-16) var(--page-padding);
  background: var(--color-gray-900); color: var(--color-white); text-align: center;
}
.newsletter-inner { max-width: 600px; margin: 0 auto; }
.newsletter-section h2 {
  font-size: clamp(1.75rem, 4vw, 2.5rem);
  font-weight: 800; letter-spacing: -0.04em; margin-bottom: var(--space-3);
}
.newsletter-inner > p { font-size: 1.0625rem; color: rgba(255,255,255,.7); margin-bottom: var(--space-8); }
.newsletter-form { text-align: left; }
.newsletter-field label {
  display: block; font-size: 0.875rem; font-weight: 600;
  margin-bottom: var(--space-2); color: rgba(255,255,255,.85);
}
.newsletter-input-row { display: flex; gap: var(--space-2); flex-wrap: wrap; }
.newsletter-input-row input[type="email"] {
  flex: 1; min-width: 200px; padding: 0.75rem 1.125rem;
  border: 1.5px solid rgba(255,255,255,.2); border-radius: var(--r-full);
  background: rgba(255,255,255,.08); color: var(--color-white);
  transition: border-color var(--t-fast), background var(--t-fast);
}
.newsletter-input-row input[type="email"]:focus { outline: none; border-color: rgba(255,255,255,.6); background: rgba(255,255,255,.12); }
.newsletter-input-row input[type="email"]:focus-visible { outline: 3px solid var(--color-accent); outline-offset: 3px; }
.newsletter-input-row input[type="email"]::placeholder { color: rgba(255,255,255,.4); }
.newsletter-input-row input[aria-invalid="true"] { border-color: #ff8a8a; }
.field-error { font-size: 0.875rem; color: #ff8a8a; margin-top: var(--space-2); }
.newsletter-privacy { font-size: 0.8125rem; color: rgba(255,255,255,.45); text-align: center; margin-top: var(--space-4); }
.newsletter-status { font-size: 0.9375rem; margin-top: var(--space-4); text-align: center; color: #7dde9f; }

/* ── Footer ─────────────────────────────────────────────────── */
.site-footer {
  background: var(--color-white);
  border-top: 1px solid var(--color-gray-100);
  padding-top: var(--space-16);
}
.footer-inner {
  max-width: var(--max-width); margin: 0 auto;
  padding: 0 var(--page-padding) var(--space-12);
  display: grid; grid-template-columns: 1.5fr 1fr 1fr 1fr 1fr; gap: var(--space-8);
}
.footer-brand p { font-size: 0.9375rem; color: var(--color-gray-600); margin-top: var(--space-4); max-width: 24ch; }
.brand-logo--footer { color: var(--color-brand); font-size: 1.125rem; }
.footer-nav h3 {
  font-size: 0.75rem; font-weight: 700; letter-spacing: .1em; text-transform: uppercase;
  color: var(--color-gray-400); margin-bottom: var(--space-4);
}
.footer-nav ul { display: flex; flex-direction: column; gap: var(--space-3); }
.footer-nav a { font-size: 0.9375rem; color: var(--color-gray-600); transition: color var(--t-fast); }
.footer-nav a:hover { color: var(--color-brand); }
.footer-social h3 {
  font-size: 0.75rem; font-weight: 700; letter-spacing: .1em; text-transform: uppercase;
  color: var(--color-gray-400); margin-bottom: var(--space-4);
}
.social-list { display: flex; gap: var(--space-3); }
.social-list a {
  display: flex; align-items: center; justify-content: center;
  width: 40px; height: 40px; border-radius: var(--r-full);
  border: 1.5px solid var(--color-gray-200); color: var(--color-gray-600);
  transition: border-color var(--t-fast), color var(--t-fast), background var(--t-fast);
}
.social-list a:hover { border-color: var(--color-brand); color: var(--color-brand); background: var(--color-gray-50); }
.footer-bottom {
  border-top: 1px solid var(--color-gray-100);
  padding: var(--space-5) var(--page-padding);
  max-width: var(--max-width); margin: 0 auto;
  display: flex; align-items: center; justify-content: space-between;
  gap: var(--space-4); flex-wrap: wrap;
}
.footer-bottom p { font-size: 0.875rem; color: var(--color-gray-400); }
.legal-links { display: flex; gap: var(--space-5); flex-wrap: wrap; }
.legal-links a { font-size: 0.875rem; color: var(--color-gray-400); }
.legal-links a:hover { color: var(--color-brand); text-decoration: underline; }

/* ── Reduced motion ─────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after {
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .01ms !important;
    scroll-behavior: auto !important;
  }
}

/* ── Forced colors ──────────────────────────────────────────── */
@media (forced-colors: active) {
  .btn-primary, .btn-add-cart { forced-color-adjust: none; border: 2px solid ButtonText; }
  .product-card, .deal-card, .editorial-card { border: 1px solid ButtonText; }
  .cart-count, .product-badge { border: 1px solid ButtonText; }
}

/* ── Responsive: tablet (≤1024px) ──────────────────────────── */
@media (max-width: 1024px) {
  .primary-nav { display: none; }
  .nav-mobile-toggle { display: flex; }
  .search-input { width: 140px; }
  .hero { grid-template-columns: 1fr; min-height: auto; gap: var(--space-8); }
  .hero-media { display: none; }
  .product-grid { grid-template-columns: repeat(2, 1fr); }
  .deals-grid { grid-template-columns: 1fr 1fr; }
  .deal-card--hero { grid-column: span 2; }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .editorial-card--large { grid-column: span 2; }
  .footer-inner { grid-template-columns: 1fr 1fr 1fr; }
  .footer-brand { grid-column: span 3; }
  .footer-social { grid-column: span 3; }
}

/* ── Responsive: mobile (≤480px) ───────────────────────────── */
@media (max-width: 480px) {
  .header-actions .search-form { display: none; }
  .category-list { grid-template-columns: repeat(3, 1fr); }
  .category-list li:nth-child(4), .category-list li:nth-child(5) { display: none; }
  .product-grid { grid-template-columns: 1fr 1fr; gap: var(--space-4); }
  .deals-grid { grid-template-columns: 1fr; }
  .deal-card--hero { grid-column: auto; }
  .editorial-grid { grid-template-columns: 1fr; }
  .editorial-card--large { grid-column: auto; }
  .footer-inner { grid-template-columns: 1fr 1fr; }
  .footer-brand { grid-column: span 2; }
  .footer-social { grid-column: span 2; }
  .footer-bottom { flex-direction: column; text-align: center; }
  .newsletter-input-row { flex-direction: column; }
  .newsletter-input-row .btn { width: 100%; }
}

/* ── Responsive: narrow (≤360px) ───────────────────────────── */
@media (max-width: 360px) {
  .product-grid { grid-template-columns: 1fr; }
  .hero h1 { font-size: 2rem; }
  .hero-actions { flex-direction: column; }
  .hero-actions .btn { width: 100%; text-align: center; }
}

/* ── Dark mode ──────────────────────────────────────────────── */
@media (prefers-color-scheme: dark) {
  :root {
    --color-white:     #0f0f12;
    --color-off-white: #16161a;
    --color-gray-50:   #1c1c22;
    --color-gray-100:  #2a2a32;
    --color-gray-200:  #3a3a44;
    --color-gray-400:  #7a7a88;
    --color-gray-600:  #a8a8b8;
    --color-gray-800:  #d0d0de;
    --color-gray-900:  #f0f0f8;
  }
  .product-card, .editorial-card { background: var(--color-gray-50); }
  .search-form { background: var(--color-gray-50); border-color: var(--color-gray-100); }
  .search-input { color: var(--color-gray-900); }
  .submenu { background: var(--color-gray-50); border-color: var(--color-gray-100); }
  .mobile-nav { background: var(--color-white); border-top-color: var(--color-gray-100); }
  .mobile-nav a { border-bottom-color: var(--color-gray-100); }
  .site-footer { background: var(--color-white); border-top-color: var(--color-gray-100); }
  .social-list a { border-color: var(--color-gray-200); }
  .editorial-meta { border-top-color: var(--color-gray-100); }
  .btn-wishlist { border-color: var(--color-gray-200); }
}
