  --color-gray-800:  #3a3834;
  --color-gray-900:  #1c1b18;

  /* Typography */
  --font-sans: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;

  /* Spacing */
  --space-1: 0.25rem; --space-2: 0.5rem; --space-3: 0.75rem; --space-4: 1rem;
  --space-5: 1.25rem; --space-6: 1.5rem; --space-8: 2rem;   --space-10: 2.5rem;
  --space-12: 3rem;   --space-16: 4rem;  --space-20: 5rem;   --space-24: 6rem;

  /* Layout */
  --max-width:    1280px;
  --page-padding: clamp(1rem, 4vw, 2.5rem);
  --header-h:     64px;

  /* Radius */
  --r-sm: 4px; --r-md: 8px; --r-lg: 16px; --r-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 3px rgba(0,0,0,.08), 0 1px 2px rgba(0,0,0,.06);
  --shadow-md: 0 4px 12px rgba(0,0,0,.10), 0 2px 6px rgba(0,0,0,.07);
  --shadow-lg: 0 10px 30px rgba(0,0,0,.12), 0 4px 10px rgba(0,0,0,.08);

  /* Transitions */
  --t-fast: 150ms ease;
  --t-base: 250ms ease;
}

/* ── Resets ─────────────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
body {
  font-family: var(--font-sans);
  font-size: 1rem;
  line-height: 1.6;
  color: var(--color-gray-900);
  background: var(--color-white);
  min-width: 320px;
}
img, video, svg { display: block; max-width: 100%; }
a  { color: inherit; text-decoration: none; }
ul[role="list"] { list-style: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
input, button { font-size: 1rem; }

/* ── Accessibility utilities ────────────────────────────────── */
.sr-only:not(:focus):not(:active) {
  clip: rect(0 0 0 0); clip-path: inset(50%);
  height: 1px; overflow: hidden;
  position: absolute; white-space: nowrap; width: 1px;
}

.skip-link {
  position: absolute; top: var(--space-3); left: var(--space-3); z-index: 9999;
  padding: var(--space-3) var(--space-5);
  background: var(--color-brand); color: var(--color-white);
  font-weight: 600; border-radius: var(--r-md); text-decoration: underline;
  transform: translateY(-120%);
  transition: transform var(--t-fast);
}
.skip-link:focus { transform: translateY(0); }

:focus-visible { outline: 3px solid var(--color-accent); outline-offset: 3px; border-radius: 2px; }
:focus:not(:focus-visible) { outline: none; }

/* ── Promo banner ───────────────────────────────────────────── */
.promo-banner {
  display: flex; align-items: center; justify-content: center;
  gap: var(--space-3); position: relative;
  background: var(--color-brand); color: var(--color-white);
  padding: var(--space-2) var(--page-padding);
  font-size: 0.875rem; text-align: center;
}
.promo-banner a { color: var(--color-white); text-decoration: underline; font-weight: 600; }
.promo-banner a:hover { opacity: .85; }
.promo-close {
  position: absolute; right: var(--page-padding); top: 50%; transform: translateY(-50%);
  color: var(--color-white); padding: var(--space-1); border-radius: var(--r-sm);
  line-height: 0; opacity: .8; transition: opacity var(--t-fast);
}
.promo-close:hover { opacity: 1; }

/* ── Site header ────────────────────────────────────────────── */
.site-header {
  position: sticky; top: 0; z-index: 100;
  background: var(--color-white);
  border-bottom: 1px solid var(--color-gray-100);
  box-shadow: var(--shadow-sm);
}
.header-inner {
  max-width: var(--max-width); margin: 0 auto;
  padding: 0 var(--page-padding); height: var(--header-h);
  display: flex; align-items: center; gap: var(--space-6);
}
.brand-logo {
  display: flex; align-items: center; gap: var(--space-2);
  color: var(--color-brand); font-weight: 700; font-size: 1.25rem;
  letter-spacing: -0.02em; flex-shrink: 0;
}

/* Primary nav */
.primary-nav { flex: 1; }
.primary-nav > ul { display: flex; gap: var(--space-1); align-items: center; }
.primary-nav a,
.primary-nav .nav-toggle {
  display: block; padding: var(--space-2) var(--space-3);
  font-size: 0.9375rem; font-weight: 500; color: var(--color-gray-800);
  border-radius: var(--r-sm);
  transition: color var(--t-fast), background var(--t-fast);
  white-space: nowrap;
}
.primary-nav a:hover, .primary-nav .nav-toggle:hover {
  color: var(--color-brand); background: var(--color-gray-50);
}
.primary-nav a[aria-current="page"] {
  color: var(--color-accent); font-weight: 600;
  text-decoration: underline; text-underline-offset: 3px;
}
.nav-toggle { display: flex; align-items: center; gap: var(--space-1); }
.nav-toggle::after {
  content: ""; display: inline-block;
  width: 0; height: 0;
  border-left: 4px solid transparent;
  border-right: 4px solid transparent;
  border-top: 5px solid currentColor;
  transition: transform var(--t-fast);
}
.nav-toggle[aria-expanded="true"]::after { transform: rotate(180deg); }

.submenu {
  position: absolute; top: calc(100% + var(--space-2)); left: 0;
  background: var(--color-white); border: 1px solid var(--color-gray-100);
  border-radius: var(--r-md); box-shadow: var(--shadow-md);
  min-width: 160px; padding: var(--space-2) 0; z-index: 200;
}
.primary-nav li { position: relative; }
.submenu a {
  display: block; padding: var(--space-2) var(--space-5);
  font-size: 0.9375rem; color: var(--color-gray-800); border-radius: 0;
}
.submenu a:hover { background: var(--color-gray-50); color: var(--color-brand); }

/* Header actions */
.header-actions { display: flex; align-items: center; gap: var(--space-2); margin-left: auto; }

.search-form {
  display: flex; align-items: center;
  background: var(--color-gray-50); border: 1px solid var(--color-gray-100);
  border-radius: var(--r-full); overflow: hidden;
  transition: border-color var(--t-fast), box-shadow var(--t-fast);
}
.search-form:focus-within {
  border-color: var(--color-brand);
  box-shadow: 0 0 0 3px rgba(26,26,46,.12);
  outline: none;
}
.search-form:focus-within :focus-visible { outline: none; }
.search-input {
  border: none; background: transparent; padding: var(--space-2) var(--space-3);
  width: 180px; color: var(--color-gray-900);
}
.search-input::placeholder { color: var(--color-gray-400); }
.search-input:focus { outline: none; }
.search-btn {
  padding: var(--space-2) var(--space-3); color: var(--color-gray-600);
  line-height: 0; transition: color var(--t-fast);
}
.search-btn:hover { color: var(--color-brand); }

.icon-btn {
  display: flex; align-items: center; justify-content: center;
  width: 40px; height: 40px; color: var(--color-gray-800);
  border-radius: var(--r-full); position: relative;
  transition: background var(--t-fast), color var(--t-fast);
}
.icon-btn:hover { background: var(--color-gray-50); color: var(--color-brand); }
.cart-count {
  position: absolute; top: 4px; right: 4px;
  background: var(--color-accent); color: var(--color-white);
  font-size: 0.625rem; font-weight: 700;
  width: 16px; height: 16px; border-radius: var(--r-full);
  display: flex; align-items: center; justify-content: center;
}

/* Mobile toggle */
.nav-mobile-toggle {
  display: none; flex-direction: column; gap: 5px;
  padding: var(--space-2); border-radius: var(--r-sm);
  color: var(--color-brand); transition: background var(--t-fast);
}
.nav-mobile-toggle:hover { background: var(--color-gray-50); }
.hamburger-bar {
  display: block; width: 22px; height: 2px; background: currentColor; border-radius: 2px;
  transition: transform var(--t-base), opacity var(--t-fast);
}
.nav-mobile-toggle[aria-expanded="true"] .hamburger-bar:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.nav-mobile-toggle[aria-expanded="true"] .hamburger-bar:nth-child(2) { opacity: 0; }
.nav-mobile-toggle[aria-expanded="true"] .hamburger-bar:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

.mobile-nav {
  border-top: 1px solid var(--color-gray-100);
  background: var(--color-white);
  padding: var(--space-4) var(--page-padding);
}
.mobile-nav a {
  display: block; padding: var(--space-3) 0;
  font-size: 1.0625rem; font-weight: 500;
  color: var(--color-gray-800); border-bottom: 1px solid var(--color-gray-100);
}
.mobile-nav a[aria-current="page"] { color: var(--color-accent); font-weight: 600; }
.mobile-nav a:hover { color: var(--color-brand); }

/* ── Section helpers ────────────────────────────────────────── */
.section-header {
  max-width: var(--max-width); margin: 0 auto;
  padding: 0 var(--page-padding); margin-bottom: var(--space-6);
  display: flex; align-items: baseline; justify-content: space-between;
}
.section-header h2 {
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-weight: 700; letter-spacing: -0.03em; color: var(--color-brand);
}
.view-all-link {
  font-size: 0.9375rem; font-weight: 500; color: var(--color-accent);
  text-decoration: underline; text-underline-offset: 3px; white-space: nowrap;
}
.view-all-link:hover { color: var(--color-accent-dark); }

/* ── Buttons ────────────────────────────────────────────────── */
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  gap: var(--space-2); padding: 0.6875rem 1.5rem;
  font-weight: 600; font-size: 0.9375rem;
  border-radius: var(--r-full);
  transition: background var(--t-fast), color var(--t-fast), transform var(--t-fast), box-shadow var(--t-fast);
  border: 2px solid transparent; white-space: nowrap;
}
.btn:active { transform: scale(.98); }
.btn-primary  { background: var(--color-brand); color: var(--color-white); border-color: var(--color-brand); }
.btn-primary:hover { background: var(--color-brand-mid); border-color: var(--color-brand-mid); box-shadow: var(--shadow-md); }
.btn-ghost    { background: transparent; color: var(--color-brand); border-color: var(--color-brand); }
.btn-ghost:hover { background: var(--color-brand); color: var(--color-white); }
.btn-outline  { background: transparent; color: var(--color-white); border-color: var(--color-white); }
.btn-outline:hover { background: var(--color-white); color: var(--color-brand); }
.btn-add-cart {
  flex: 1; background: var(--color-brand); color: var(--color-white);
  padding: 0.5rem 1rem; border-radius: var(--r-full);
  font-size: 0.875rem; font-weight: 600;
  transition: background var(--t-fast);
}
.btn-add-cart:hover { background: var(--color-brand-mid); }
.btn-wishlist {
  display: flex; align-items: center; justify-content: center;
  width: 38px; height: 38px; border-radius: var(--r-full);
  border: 1.5px solid var(--color-gray-200); color: var(--color-gray-400);
  flex-shrink: 0;
  transition: color var(--t-fast), border-color var(--t-fast), background var(--t-fast);
}
.btn-wishlist:hover, .btn-wishlist[aria-pressed="true"] {
  color: var(--color-accent); border-color: var(--color-accent);
}
.btn-wishlist[aria-pressed="true"] svg { fill: var(--color-accent); stroke: var(--color-accent); }

/* ── Hero ───────────────────────────────────────────────────── */
.hero {
  max-width: var(--max-width); margin: 0 auto;
  padding: var(--space-12) var(--page-padding);
  display: grid; grid-template-columns: 1fr 1fr;
  gap: var(--space-12); align-items: center; min-height: 520px;
}
.hero-eyebrow {
  font-size: 0.8125rem; font-weight: 600;
  letter-spacing: 0.12em; text-transform: uppercase;
  color: var(--color-accent); margin-bottom: var(--space-4);
}
.hero h1 {
  font-size: clamp(2.5rem, 5vw, 4rem);
  font-weight: 800; letter-spacing: -0.04em; line-height: 1.1;
  color: var(--color-brand); margin-bottom: var(--space-5);
}
.hero-sub {
  font-size: 1.125rem; color: var(--color-gray-600);
  margin-bottom: var(--space-8); max-width: 38ch;
}
.hero-actions { display: flex; gap: var(--space-3); flex-wrap: wrap; }
.hero-media { position: relative; }
.hero-image-placeholder {
  border-radius: var(--r-lg); overflow: hidden;
  aspect-ratio: 4/5;
}
.hero-img-inner {
  width: 100%; height: 100%;
  background: linear-gradient(135deg, #e8ddd4 0%, #c9b8a8 35%, #a89080 60%, #7a6055 100%);
}

/* ── Category rail ──────────────────────────────────────────── */
.category-rail { background: var(--color-off-white); padding: var(--space-12) var(--page-padding); }
.category-list {
  max-width: var(--max-width); margin: 0 auto;
  display: grid; grid-template-columns: repeat(5, 1fr); gap: var(--space-4);
}
.category-card {
  display: flex; flex-direction: column; align-items: center; gap: var(--space-3);
  color: var(--color-gray-800); font-size: 0.9375rem; font-weight: 600;
  transition: color var(--t-fast);
}
.category-card:hover { color: var(--color-brand); }
.category-card:hover .category-thumb { transform: scale(1.04); }
.category-thumb {
  width: 100%; aspect-ratio: 1; border-radius: var(--r-lg);
  transition: transform var(--t-base); overflow: hidden;
}
.category-thumb--women      { background: linear-gradient(135deg, #f5e6d3, #d4a0a0); }
.category-thumb--men        { background: linear-gradient(135deg, #d3e0f5, #8090b0); }
.category-thumb--accessories { background: linear-gradient(135deg, #f5f0d3, #d4c080); }
.category-thumb--home       { background: linear-gradient(135deg, #d3f5e6, #80c4a0); }
.category-thumb--beauty     { background: linear-gradient(135deg, #f5d3e6, #d480a8); }

/* ── Products ───────────────────────────────────────────────── */
.products-section { padding: var(--space-16) 0; }
.product-grid {
  max-width: var(--max-width); margin: 0 auto; padding: 0 var(--page-padding);
  display: grid; grid-template-columns: repeat(4, 1fr); gap: var(--space-6);
}
.product-card {
  border-radius: var(--r-lg); overflow: hidden;
  background: var(--color-white); box-shadow: var(--shadow-sm);
  transition: box-shadow var(--t-base), transform var(--t-base);
}
.product-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-2px); }
.product-image-wrap { position: relative; overflow: hidden; }
.product-image { aspect-ratio: 3/4; transition: transform var(--t-base); }
.product-card:hover .product-image { transform: scale(1.04); }
.product-image--1 { background: linear-gradient(160deg, #e8d8c4 0%, #c8a880 100%); }
.product-image--2 { background: linear-gradient(160deg, #f5ede0 0%, #d4b89c 100%); }
.product-image--3 { background: linear-gradient(160deg, #f0ebe3 0%, #c8bfb0 100%); }
.product-image--4 { background: linear-gradient(160deg, #d8c4a0 0%, #a08060 100%); }
.product-badge {
  position: absolute; top: var(--space-3); left: var(--space-3);
  padding: 2px 10px; border-radius: var(--r-full);
  font-size: 0.75rem; font-weight: 700; letter-spacing: .05em; text-transform: uppercase;
  background: var(--color-brand); color: var(--color-white);
}
.product-badge--sale       { background: var(--color-accent); }
.product-badge--bestseller { background: #9c6a00; }
.product-info { padding: var(--space-4); }
.product-brand {
  font-size: 0.75rem; font-weight: 600; letter-spacing: .08em;
  text-transform: uppercase; color: var(--color-gray-400); margin-bottom: var(--space-1);
}
.product-name { font-size: 0.9375rem; font-weight: 600; margin-bottom: var(--space-2); line-height: 1.3; }
.product-name a { color: var(--color-gray-900); }
.product-name a:hover { color: var(--color-brand); text-decoration: underline; text-underline-offset: 2px; }
.product-price { font-size: 1rem; font-weight: 700; color: var(--color-brand); margin-bottom: var(--space-4); }
.price-current  { color: var(--color-accent); }
.price-original { font-size: 0.875rem; font-weight: 400; color: var(--color-gray-400); margin-left: var(--space-2); }
.product-actions { display: flex; gap: var(--space-2); align-items: center; }

/* ── Deals ──────────────────────────────────────────────────── */
.deals-section { padding: var(--space-16) 0; background: var(--color-brand); }
.deals-section .section-header h2 { color: var(--color-white); }
.deals-section .view-all-link { color: rgba(255,255,255,.8); }
.deals-section .view-all-link:hover { color: var(--color-white); }
.deals-grid {
  max-width: var(--max-width); margin: 0 auto; padding: 0 var(--page-padding);
  display: grid; grid-template-columns: 1.6fr 1fr 1fr; gap: var(--space-5);
}
.deal-card {
  border-radius: var(--r-lg); overflow: hidden;
  background: var(--color-brand-mid); position: relative;
  display: flex; flex-direction: column;
}
.deal-card--hero { grid-row: span 2; }
.deal-image { flex: 1; min-height: 200px; }
.deal-card--hero .deal-image { min-height: 340px; }
.deal-image--1 { background: linear-gradient(160deg, #3a4a7a 0%, #8090c0 100%); }
.deal-image--2 { background: linear-gradient(160deg, #2a4060 0%, #6080a0 100%); }
.deal-image--3 { background: linear-gradient(160deg, #1a3050 0%, #4070a0 100%); }
.deal-content { padding: var(--space-5) var(--space-6); color: var(--color-white); }
.deal-tag {
  display: inline-block; background: var(--color-accent); color: var(--color-white);
  font-size: 0.6875rem; font-weight: 700; letter-spacing: .1em; text-transform: uppercase;
  padding: 3px 10px; border-radius: var(--r-full); margin-bottom: var(--space-3);
}
.deal-content h3 {
  font-size: clamp(1.125rem, 2vw, 1.5rem);
  font-weight: 700; letter-spacing: -0.02em; margin-bottom: var(--space-2);
}
.deal-content p { font-size: 0.9375rem; color: rgba(255,255,255,.75); margin-bottom: var(--space-5); }

/* ── Editorial ──────────────────────────────────────────────── */
.editorial-section { padding: var(--space-16) 0; background: var(--color-off-white); }
.editorial-grid {
  max-width: var(--max-width); margin: 0 auto; padding: 0 var(--page-padding);
  display: grid; grid-template-columns: 1.5fr 1fr 1fr; gap: var(--space-6);
}
.editorial-card {
  border-radius: var(--r-lg); overflow: hidden;
  background: var(--color-white); box-shadow: var(--shadow-sm);
  transition: box-shadow var(--t-base), transform var(--t-base);
  display: flex; flex-direction: column;
}
.editorial-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-2px); }
.editorial-image { aspect-ratio: 16/9; transition: transform var(--t-base); overflow: hidden; }
.editorial-card--large .editorial-image { aspect-ratio: 4/3; }
.editorial-card:hover .editorial-image { transform: scale(1.03); }
.editorial-image--1 { background: linear-gradient(135deg, #d4e8c4 0%, #8cb080 100%); }
.editorial-image--2 { background: linear-gradient(135deg, #f5e4d0 0%, #d4a080 100%); }
.editorial-image--3 { background: linear-gradient(135deg, #d4e4f5 0%, #80a0c4 100%); }
.editorial-content { padding: var(--space-5); flex: 1; display: flex; flex-direction: column; }
.editorial-tag {
  display: inline-block; font-size: 0.6875rem; font-weight: 700;
  letter-spacing: .1em; text-transform: uppercase; color: var(--color-accent);
  margin-bottom: var(--space-2);
}
.editorial-content h3 { font-size: 1.0625rem; font-weight: 700; line-height: 1.35; margin-bottom: var(--space-2); flex: 1; }
.editorial-card--large .editorial-content h3 { font-size: 1.375rem; }
.editorial-content h3 a { color: var(--color-gray-900); }
.editorial-content h3 a:hover { color: var(--color-brand); text-decoration: underline; text-underline-offset: 2px; }
.editorial-content p { font-size: 0.9rem; color: var(--color-gray-600); margin-bottom: var(--space-3); }
.editorial-meta {
  font-size: 0.8125rem; color: var(--color-gray-400);
  margin-top: auto; padding-top: var(--space-3);
  border-top: 1px solid var(--color-gray-100);
}

/* ── Newsletter ─────────────────────────────────────────────── */
.newsletter-section {
  padding: var(--space-16) var(--page-padding);
  background: var(--color-gray-900); color: var(--color-white); text-align: center;
}
.newsletter-inner { max-width: 600px; margin: 0 auto; }
.newsletter-section h2 {
  font-size: clamp(1.75rem, 4vw, 2.5rem);
  font-weight: 800; letter-spacing: -0.04em; margin-bottom: var(--space-3);
}
.newsletter-inner > p { font-size: 1.0625rem; color: rgba(255,255,255,.7); margin-bottom: var(--space-8); }
.newsletter-form { text-align: left; }
.newsletter-field label {
  display: block; font-size: 0.875rem; font-weight: 600;
  margin-bottom: var(--space-2); color: rgba(255,255,255,.85);
}
.newsletter-input-row { display: flex; gap: var(--space-2); flex-wrap: wrap; }
.newsletter-input-row input[type="email"] {
  flex: 1; min-width: 200px; padding: 0.75rem 1.125rem;
  border: 1.5px solid rgba(255,255,255,.2); border-radius: var(--r-full);
  background: rgba(255,255,255,.08); color: var(--color-white);
  transition: border-color var(--t-fast), background var(--t-fast);
}
.newsletter-input-row input[type="email"]:focus { outline: none; border-color: rgba(255,255,255,.6); background: rgba(255,255,255,.12); }
.newsletter-input-row input[type="email"]:focus-visible { outline: 3px solid var(--color-accent); outline-offset: 3px; }
.newsletter-input-row input[type="email"]::placeholder { color: rgba(255,255,255,.4); }
.newsletter-input-row input[aria-invalid="true"] { border-color: #ff8a8a; }
.field-error { font-size: 0.875rem; color: #ff8a8a; margin-top: var(--space-2); }
.newsletter-privacy { font-size: 0.8125rem; color: rgba(255,255,255,.45); text-align: center; margin-top: var(--space-4); }
.newsletter-status { font-size: 0.9375rem; margin-top: var(--space-4); text-align: center; color: #7dde9f; }

/* ── Footer ─────────────────────────────────────────────────── */
.site-footer {
