// Quick manual checks via Playwright: visible focus, interactive elements, heading order
const { chromium } = require('playwright');
const fs = require('fs');

(async () => {
  const html = fs.readFileSync('index.html', 'utf8');
  const css  = fs.readFileSync('styles.css', 'utf8');
  const js   = fs.readFileSync('main.js',    'utf8');
  const inlined = html
    .replace('<link rel="stylesheet" href="styles.css">', '<style>' + css + '</style>')
    .replace('<script src="main.js"></script>', '<script>' + js + '</script>');

  const browser = await chromium.launch();
  const page    = await browser.newPage();
  await page.setViewportSize({ width: 1280, height: 900 });
  await page.setContent(inlined, { waitUntil: 'networkidle' });

  const checks = await page.evaluate(() => {
    // Heading outline
    const headings = [...document.querySelectorAll('h1,h2,h3,h4,h5,h6')].map(h => ({
      level: parseInt(h.tagName[1]),
      text: h.textContent.trim().slice(0, 60)
    }));

    // Interactive elements without accessible names
    const unnamed = [...document.querySelectorAll('button,a,input,[role="button"]')]
      .filter(el => {
        const name = (el.getAttribute('aria-label') || el.getAttribute('aria-labelledby') ||
          el.textContent.trim() || el.getAttribute('alt') || el.getAttribute('title') || '').trim();
        return !name;
      })
      .map(el => ({ tag: el.tagName, outerHTML: el.outerHTML.slice(0, 120) }));

    // Img/role=img without alt/aria-label
    const badImages = [...document.querySelectorAll('img,[role="img"]')]
      .filter(el => !el.getAttribute('alt') && !el.getAttribute('aria-label') && !el.getAttribute('aria-labelledby'))
      .map(el => el.outerHTML.slice(0, 120));

    // All nav landmark names
    const navs = [...document.querySelectorAll('nav')].map(n =>
      n.getAttribute('aria-label') || n.getAttribute('aria-labelledby') || '(unlabelled)');

    // Skip link present
    const skipLink = document.querySelector('a[href="#maincontent"]');
    const main = document.querySelector('main#maincontent');

    // Check for nested interactive elements
    const nestedInteractive = [];
    document.querySelectorAll('a').forEach(a => {
      const inner = a.querySelector('button,a');
      if (inner) nestedInteractive.push(a.outerHTML.slice(0, 100));
    });
    document.querySelectorAll('button').forEach(b => {
      const inner = b.querySelector('button,a');
      if (inner) nestedInteractive.push(b.outerHTML.slice(0, 100));
    });

    return { headings, unnamed, badImages, navs, skipLink: !!skipLink, mainTabindex: main ? main.getAttribute('tabindex') : null, nestedInteractive };
  });

  await browser.close();
  console.log(JSON.stringify(checks, null, 2));
})();
