const { chromium } = require('playwright');
const fs = require('fs');
(async () => {
  const html = fs.readFileSync('index.html', 'utf8');
  const css  = fs.readFileSync('styles.css', 'utf8');
  const js   = fs.readFileSync('main.js',    'utf8');
  const inlined = html
    .replace('<link rel="stylesheet" href="styles.css">', '<style>' + css + '</style>')
    .replace('<script src="main.js"></script>', '<script>' + js + '</script>');

  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.setViewportSize({ width: 1280, height: 900 });
  await page.setContent(inlined, { waitUntil: 'networkidle' });

  const sizes = await page.evaluate(() =>
    [...document.querySelectorAll('.social-list a')].map(a => {
      const r = a.getBoundingClientRect();
      return { label: a.getAttribute('aria-label'), w: Math.round(r.width), h: Math.round(r.height) };
    })
  );
  console.log('Social link sizes:', JSON.stringify(sizes));

  await page.addScriptTag({ path: require.resolve('axe-core') });
  const r = await page.evaluate(async () =>
    window.axe.run(document, { runOnly: { type: 'tag', values: ['wcag2a','wcag2aa','wcag21a','wcag21aa','wcag22aa'] } })
  );
  await browser.close();

  console.log('Violations:', r.violations.length);
  r.violations.forEach(v => console.log(' -', v.id, v.impact));
  process.exit(r.violations.length ? 1 : 0);
})();
