const { chromium } = require('playwright');
const fs = require('fs');

(async () => {
  const html = fs.readFileSync('index.html', 'utf8');
  const css  = fs.readFileSync('styles.css', 'utf8');
  const js   = fs.readFileSync('main.js',    'utf8');
  const inlined = html
    .replace('<link rel="stylesheet" href="styles.css">', '<style>' + css + '</style>')
    .replace('<script src="main.js"></script>', '<script>' + js + '</script>');

  const browser = await chromium.launch();
  const page    = await browser.newPage();
  await page.setViewportSize({ width: 1280, height: 900 });
  await page.setContent(inlined, { waitUntil: 'networkidle' });
  await page.addScriptTag({ path: require.resolve('axe-core') });

  const r1 = await page.evaluate(async () =>
    window.axe.run(document, { runOnly: { type: 'tag', values: ['wcag2a','wcag2aa','wcag21a','wcag21aa','wcag22aa'] } })
  );

  // Also test with submenu open
  await page.click('.nav-toggle');
  await page.addScriptTag({ path: require.resolve('axe-core') });
  const r2 = await page.evaluate(async () =>
    window.axe.run(document, { runOnly: { type: 'tag', values: ['wcag2a','wcag2aa','wcag21a','wcag21aa','wcag22aa'] } })
  );

  await browser.close();

  const seen = new Set();
  const violations = [...r1.violations, ...r2.violations].filter(v => {
    if (seen.has(v.id)) return false; seen.add(v.id); return true;
  });

  console.log(JSON.stringify({
    result: violations.length === 0 ? '✅ PASS' : '❌ FAIL',
    strategy: 'Node + Playwright + axe-core, WCAG 2.0/2.1/2.2 AA tags, default + submenu-open states',
    violations: violations.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })),
    passes: r1.passes.length
  }, null, 2));

  process.exit(violations.length ? 1 : 0);
})();
